skills.card:
base64Decode — Decode plain base64 back into readable text — un-base64 a string.
  needs: base64: string
  e.g. "decode aGVsbG8gd29ybGQ=" → {"base64":"aGVsbG8gd29ybGQ="}

binaryDecode — Read a run of 1s and 0s back into the message it spells.
  needs: binary: string
  e.g. "decode this binary" → {"binary":"01000001"}

caesarShift — Shift every letter along the alphabet by a fixed amount, as a Caesar cipher.
  needs: text: string, shift: integer
  e.g. "caesar shift hello by 3" → {"text":"hello","shift":3}

compressText — Squash text down into a shorter base64 string to store or send.
  needs: text: string
  e.g. "compress this repeated sentence" → {"text":"the pigeon sat on the pigeon perch. the pigeon sat on the pigeon perch. the pigeon sat on the pigeon perch. "}

decompressText — Unpack a compressed base64 blob back into the text it came from.
  needs: compressed: string
  e.g. "decompress this string" → {"compressed":"AAAAbDoaDKIDgaTOZTebhAczCdBBCBBAIFBINDzgZTkYzQLohAYHBYPCYXDYfEY9FITFoxGo5Eo/D5FDoTJYnIIHF4zGwA=="}

generatePassphrase — Generate a memorable passphrase from random words.
  optional: words: integer, separator: string, capitalise: boolean, number: boolean
  e.g. "generate a passphrase" → {}

generateRandomString — Generate a random string of a given length from a character set you choose.
  optional: length: integer, charset: string
  e.g. "generate a random string" → {}

generateUuid — Generate a UUID — a GUID, a v4 random identifier — one or several.
  optional: count: integer, uppercase: boolean
  e.g. "generate a uuid" → {}

hexDecode — Read hex byte values back as the characters they stand for.
  needs: hex: string
  e.g. "decode 506967656f6e" → {"hex":"506967656f6e"}

morseDecode — Read dots and dashes back as the words they spell.
  needs: morse: string
  e.g. "decode ... --- ..." → {"morse":"... --- ..."}

morseEncode — Write words out as Morse dots and dashes.
  needs: text: string
  e.g. "morse code for SOS" → {"text":"SOS"}

rot13 — Apply the ROT13 letter substitution, which is its own reverse.
  needs: text: string
  e.g. "rot13 this text" → {"text":"Hello"}

checkAnagram — Check whether two words or phrases use exactly the same letters.
  needs: first: string, second: string
  e.g. "are listen and silent anagrams" → {"first":"listen","second":"silent"}

magicEightBall — Give a magic eight ball answer to a yes or no question.
  optional: question: string
  e.g. "magic eight ball, will it rain tomorrow" → {"question":"will it rain tomorrow"}

scrabbleScore — Add up what a word is worth in Scrabble tile values.
  needs: word: string
  e.g. "what does pigeon score in scrabble" → {"word":"pigeon"}

solveAnagram — Rearrange all the letters of a word into the other words they spell.
  needs: letters: string
  e.g. "unscramble listen" → {"letters":"listen"}

